package store

import (
	"context"
	"testing"
)

func TestGSRWitness(t *testing.T) {
	r := &MemReader{Err: ErrRetry}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	_, _ = Fetch(ctx, r, "k")
	if r.Reads() >= 3 {
		t.Fatalf("Fetch with a cancelled context made %d reads, want fewer than 3", r.Reads())
	}
}
